svg.script:
// 動態計算路徑長度，確保電流動畫完整走完整條筆劃
(function() {
  var strokeEl = document.getElementById('ag-stroke-layer');
  if (!strokeEl || !strokeEl.getTotalLength) return;

  var len = strokeEl.getTotalLength();
  strokeEl.style.strokeDasharray = len;
  strokeEl.style.strokeDashoffset = len;

  // 電流動畫：2.5s 內從頭寫到尾，然後 fade out
  strokeEl.style.transition =
    'stroke-dashoffset 2.5s cubic-bezier(0.3,0,0.7,1) 0.2s, ' +
    'opacity 0.4s ease 2.7s';

  // 觸發動畫（需要 rAF 確保樣式已套用）
  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      strokeEl.style.strokeDashoffset = '0';
      // 2.7s 後 fade out（電流消失，讓 fill 層接手）
      setTimeout(function() {
        strokeEl.style.opacity = '0';
      }, 2700);
    });
  });
})();
